WITH scored AS (SELECT id, customer_id, status, MAX(monthly_fee) OVER w_ordered AS last3_max_monthly_fee, MIN(monthly_fee) OVER w_ordered AS last3_min_monthly_fee, AVG(monthly_fee) OVER w_ordered AS last3_avg_monthly_fee, COUNT(monthly_fee) OVER w_ordered AS last3_count_monthly_fee FROM subscriptions WHERE end_date > '2025-02-01' WINDOW w_ordered AS (PARTITION BY status, customer_id ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT id, status, last3_max_monthly_fee, last3_min_monthly_fee, last3_avg_monthly_fee, last3_count_monthly_fee, CASE WHEN status RLIKE '^(PAUSED|ACTIVE)$' THEN 'CORE' ELSE 'GROUP_B' END AS status_zone FROM scored ORDER BY last3_avg_monthly_fee ASC
